// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint64 ts, uint256 warpAhead) public {
        // first call at some admissible timestamp
        uint64 t1 = uint64(bound(uint256(ts), 1, 1e12));
        vm.warp(t1);
        address actor = address(0xA11CE);
        vm.deal(actor, 20 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // second successful call strictly later; any warpAhead >= 1 keeps it admissible
        uint64 t2 = t1 + uint64(bound(warpAhead, 1, 1e12));
        vm.warp(t2);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        c.fallback{value: 10 ether}();

        // Rule: pastBlockTime always equals the timestamp of the most recent successful call
        assertTrue(c.pastBlockTime() == block.timestamp);
    }
}

