pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(c) && actor != address(0));
        t = bound(t, 1, type(uint256).max - 1);

        vm.warp(t);
        vm.deal(actor, 10 ether);

        // First call at time t: succeeds in both versions.
        vm.prank(actor);
        (bool ok1,) = address(c).call{value: 10 ether}("");
        assertTrue(ok1);

        // Rule: after a successful call at time t, a call at a timestamp not
        // greater than t must revert (pastBlockTime was set to t).
        vm.prank(actor);
        (bool ok2,) = address(c).call{value: 10 ether}("");
        assertTrue(!ok2);
    }
}

