pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 t, address actor) public {
        vm.assume(actor != address(0));
        vm.assume(t > block.timestamp);

        vm.warp(t);

        uint256 amt = 10 ether;
        vm.deal(actor, amt);
        vm.prank(actor);
        (bool ok1, ) = address(c).call{value: amt}("");
        assertTrue(ok1);

        // second call in the SAME block.timestamp must be rejected by P
        vm.deal(actor, amt);
        vm.prank(actor);
        bool ok2;
        try c.fallback{value: amt}() { ok2 = true; } catch { ok2 = false; }

        // General rule: no two fallback calls may succeed at the same block.timestamp.
        assertTrue(!ok2, "second call in same timestamp must revert");
    }
}

