        vm.warp(t2);
        vm.deal(actor, 10 ether);
        bool ok;
        vm.prank(actor);
        try c.fallback{value: 10 ether}() {
            ok = true;
        } catch {
            ok = false;
        }

        // Rule: the second (later-timestamped) call must succeed and pastBlockTime
        // must reflect that later timestamp.
        assertTrue(ok && c.pastBlockTime() == t2);
    }
