pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 amount, uint256 warpTime) public {
        vm.assume(amount <= address(this).balance + type(uint256).max / 2);
        vm.assume(amount <= 1_000_000 ether);
        vm.warp(1_000_000 + (warpTime % 1_000_000));
        address actor = makeAddr("actor");
        vm.deal(actor, amount);
        vm.prank(actor);
        bool ok;
        if (amount == 0) {
            ok = false; // cannot send zero value to a payable fallback? it can; keep wide
        }
        try c.fallback{value: amount}() {
            ok = true;
        } catch {
            ok = false;
        }
        // General rule: the reference C accepts EVERY call (its only value gate is
        // == 10 ether, which is satisfiable, and the timestamp gate holds on a fresh
        // block). In particular, a call sending exactly 10 ether must succeed.
        // The mutant (msg.value != 10 ether) reverts on that 10-ether input.
        assertTrue(ok || amount != 10 ether, "10 ether call must be accepted");
    }
}

