// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;

    function setUp() public { c = new C{value: 10 ether}(); }

    function testFuzz_property(uint256 n, uint256 ts) public {
        // keep the fuzzed block number in a wide admissible domain
        n = bound(n, 0, 10_000_000);
        // any strictly increasing timestamp is admissible
        vm.warp(1 + (ts % 1_000_000));
        vm.roll(n);

        // drive c through its payable fallback with exactly 10 ether
        address actor = address(0xA11CE);
        vm.deal(actor, 10 ether);
        vm.prank(actor);
        (bool ok,) = address(c).call{value: 10 ether}("");
        assertTrue(ok, "valid deposit should not revert");

        // General rule: a non-payout block (n % 15 != 0) leaves c holding exactly
        // its 10-ether deposit; the mutant pays at n % 15 == 1 and breaks this.
        if (n % 15 != 0) {
            assertEq(address(c).balance, 10 ether);
        } else {
            assertEq(address(c).balance, 0);
        }
    }
}

